import type { Certificate, CertificatePEM, KeyObject, PrivateKey, PrivateKeyPEM, PublicKey, PublicKeyPEM } from "../source/common.js";
/**
 * Read a DER or PEM certificate from file.
 *
 * **Note:** If the PEM file contains multiple certificate blocks
 * (e.g. a leaf cert + CA chain), only the **first** certificate
 * is returned. Use {@link readCertificateChain} to read all
 * certificates individually.
 *
 * @deprecated Use {@link readCertificateChain} instead, which
 * returns each certificate as a separate DER buffer.
 */
export declare function readCertificate(filename: string): Certificate;
/**
 * Read a PEM or DER certificate file that may contain multiple
 * certificates (e.g. a leaf cert + CA issuer chain) and return
 * each certificate as a separate DER `Buffer`.
 *
 * - For a DER file, returns a single-element array.
 * - For a PEM file with N certificate blocks, returns N elements
 *   in the same order they appear in the file (leaf first).
 */
export declare function readCertificateChain(filename: string): Certificate[];
/**
 * Async version of {@link readCertificateChain}.
 */
export declare function readCertificateChainAsync(filename: string): Promise<Certificate[]>;
/**
 * Async version of {@link readCertificate}.
 * Uses `fs.promises.readFile` so the event loop is not blocked
 * during I/O.
 *
 * **Note:** If the PEM file contains multiple certificate blocks,
 * only the first is returned. Use {@link readCertificateChainAsync}.
 *
 * @deprecated Use {@link readCertificateChainAsync} instead.
 */
export declare function readCertificateAsync(filename: string): Promise<Certificate>;
/**
 * read a DER or PEM certificate from file
 */
export declare function readPublicKey(filename: string): KeyObject;
/**
 * Async version of {@link readPublicKey}.
 */
export declare function readPublicKeyAsync(filename: string): Promise<KeyObject>;
/**
 * read a DER or PEM certificate from file
 *
 * @param filename
 * @param passphrase — required if the key is an encrypted PKCS#8 PEM
 *   (`-----BEGIN ENCRYPTED PRIVATE KEY-----`). Throws
 *   {@link PrivateKeyPassphraseRequiredError} if the key is encrypted and
 *   no passphrase is supplied.
 */
export declare function readPrivateKey(filename: string, passphrase?: string | Buffer): PrivateKey;
/**
 * Async version of {@link readPrivateKey}.
 */
export declare function readPrivateKeyAsync(filename: string, passphrase?: string | Buffer): Promise<PrivateKey>;
export declare function readCertificatePEM(filename: string): CertificatePEM;
/**
 * Async version of {@link readCertificatePEM}.
 */
export declare function readCertificatePEMAsync(filename: string): Promise<CertificatePEM>;
export declare function readPublicKeyPEM(filename: string): PublicKeyPEM;
/**
 * Async version of {@link readPublicKeyPEM}.
 */
export declare function readPublicKeyPEMAsync(filename: string): Promise<PublicKeyPEM>;
/**
 *
 * @deprecated
 */
export declare function readPrivateKeyPEM(filename: string): PrivateKeyPEM;
/**
 * Async version of {@link readPrivateKeyPEM}.
 * @deprecated
 */
export declare function readPrivateKeyPEMAsync(filename: string): Promise<PrivateKeyPEM>;
export declare function setCertificateStore(store: string): string;
export declare function getCertificateStore(): string;
/**
 *
 * @param filename
 */
export declare function readPrivateRsaKey(filename: string): PrivateKey;
export declare function readPublicRsaKey(filename: string): PublicKey;
